import numpy as np


def enl(patch):
    a = np.asarray(patch, dtype=np.float64)
    s = a.std(ddof=0)
    return float((a.mean() / s) ** 2)


def multilook_2x2(image):
    a = np.asarray(image, dtype=np.float64)
    H, W = a.shape
    return (a[0:H:2, 0:W:2] + a[1:H:2, 0:W:2] + a[0:H:2, 1:W:2] + a[1:H:2, 1:W:2]) / 4.0
